#dyn-message-theme[data-theme="tmpl-neon-nightclub"]  {
  --off-ms: 680ms;
  --p-hot:  color-mix(in srgb, var(--primary) 45%, white);
  --p-soft: color-mix(in srgb, var(--primary) 55%, transparent);
  --p-haze: color-mix(in srgb, var(--primary) 28%, transparent);
  --s-hot:  color-mix(in srgb, var(--secondary) 42%, white);
  --s-soft: color-mix(in srgb, var(--secondary) 55%, transparent);
  --s-haze: color-mix(in srgb, var(--secondary) 28%, transparent);
  background: #000;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .dyn-stage  {
  background:
    radial-gradient(110cqw 60cqh at 30% 106%, rgba(46, 78, 120, .28), transparent 62%),
    radial-gradient(90cqw 55cqh at 80% 108%, rgba(70, 48, 110, .20), transparent 60%),
    radial-gradient(120cqw 80cqh at 70% -20%, rgba(20, 30, 60, .35), transparent 60%),
    linear-gradient(180deg, #04060e 0%, #060a18 60%, #081020 100%);
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .lasers  {
   position: absolute;
   inset: 0;
   z-index: 1;
   pointer-events: none;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .beam  {
  position: absolute;
   top: -14cqh;
   left: var(--x, 7cqw);
  width: 5px;
   height: 175cqh;
  transform-origin: top center;
  background: linear-gradient(to bottom,
    rgba(120, 255, 155, 0.85) 0%,
    rgba(120, 255, 155, 0.72) 16%,
    rgba(120, 255, 155, 0.34) 52%,
    transparent 90%);
  filter: blur(1px) drop-shadow(0 0 11px rgba(120, 255, 155, .85));
  animation: dynNeonSweep var(--sweep, 18s) ease-in-out infinite alternate;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .beam.wide  {
  width: 28px;
   opacity: .38;
   filter: blur(13px);
}
@keyframes dynNeonSweep  {
  from  {
   transform: rotate(calc(var(--a) - 2.2deg));
   }
  to    {
   transform: rotate(calc(var(--a) + 2.6deg));
   }
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .fog  {
  position: absolute;
   z-index: 2;
   pointer-events: none;
   border-radius: 50%;
  filter: blur(52px);
   animation: dynNeonDrift var(--dur, 40s) ease-in-out infinite alternate;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .fog.f1  {
   width: 72cqw;
   height: 58cqh;
   left: 20%;
   top: 38%;
  background: radial-gradient(closest-side, rgba(198,210,232,.36), transparent 74%);
   --dur: 46s;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .fog.f2  {
   width: 56cqw;
   height: 48cqh;
   left: 44%;
   top: 6%;
  background: radial-gradient(closest-side, rgba(205,215,240,.26), transparent 72%);
   --dur: 36s;
   animation-delay: -14s;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .fog.f3  {
   width: 62cqw;
   height: 44cqh;
   left: -12%;
   top: 56%;
  background: radial-gradient(closest-side, rgba(185,198,225,.30), transparent 72%);
   --dur: 52s;
   animation-delay: -26s;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .fog.f4  {
   width: 46cqw;
   height: 44cqh;
   left: 38%;
   top: 40%;
   z-index: 5;
  background: radial-gradient(closest-side, rgba(210,220,245,.32), transparent 70%);
   --dur: 30s;
   animation-delay: -8s;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .fog.f5  {
   width: 48cqw;
   height: 32cqh;
   left: 46%;
   top: 60%;
   z-index: 12;
  background: radial-gradient(closest-side, rgba(215,225,248,.15), transparent 70%);
   --dur: 38s;
   animation-delay: -18s;
   }
@keyframes dynNeonDrift  {
  from  {
   transform: translate(-6cqw, 2cqh) scale(1);
   }
  to    {
   transform: translate(6cqw, -2.5cqh) scale(1.14);
   }
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .vignette  {
  position: absolute;
   inset: 0;
   z-index: 6;
   pointer-events: none;
  background: radial-gradient(118cqw 104cqh at 50% 46%, transparent 62%, rgba(0,0,0,.42) 100%);
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .photo-wrap  {
  position: absolute;
   z-index: 10;
  left: 4cqw;
   top: 50%;
   transform: translateY(-50%);
  height: 92cqh;
   aspect-ratio: 700 / 1000;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .photo-wrap svg  {
  position: absolute;
   inset: 0;
   width: 100%;
   height: 100%;
   overflow: visible;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .photo-holder  {
  position: absolute;
   left: 13.15%;
   top: 9.2%;
  width: 73.7%;
   height: 81.6%;
  border-radius: 4.6cqh;
   overflow: hidden;
  box-shadow: 0 0 6cqh rgba(0,0,0,.8);
  opacity: 0;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .photo-holder img  {
  display: block;
   width: 100%;
   height: 100%;
  object-fit: cover;
  filter: saturate(1.15) contrast(1.06) brightness(.95);
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .photo-holder::after  {
  content: "";
   position: absolute;
   inset: 0;
  background: linear-gradient(160deg,
    color-mix(in srgb, var(--primary) 65%, transparent) 0%,
    transparent 42%,
    color-mix(in srgb, var(--secondary) 65%, transparent) 100%);
  opacity: .24;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .photo-holder::before  {
  content: "";
   position: absolute;
   inset: 0;
   z-index: 1;
  border-radius: inherit;
  box-shadow:
    inset 0 0 9cqh color-mix(in srgb, var(--secondary) 28%, transparent),
    inset 0 0 3cqh color-mix(in srgb, var(--primary) 22%, transparent);
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .tr  {
   fill: none;
   stroke: var(--tube);
   stroke-linecap: round;
   stroke-linejoin: round;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .tr.glow2  {
   stroke-width: 30;
   filter: blur(24px);
   opacity: .5;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .tr.glow1  {
   stroke-width: 13;
   filter: blur(7px);
    opacity: .85;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .tr.core   {
   stroke-width: 5;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .tr.hot    {
   stroke-width: 2.2;
   stroke: color-mix(in srgb, var(--tube) 30%, white);
   opacity: .95;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .trace  {
   opacity: 0;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .trace:nth-child(1)  {
   --tube: var(--primary);
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .trace:nth-child(2)  {
   --tube: color-mix(in srgb, var(--primary) 68%, var(--secondary));
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .trace:nth-child(3)  {
   --tube: color-mix(in srgb, var(--primary) 32%, var(--secondary));
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .trace:nth-child(4)  {
   --tube: var(--secondary);
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .panel  {
  position: absolute;
   z-index: 11;
  left: 44.5cqw;
   right: 5cqw;
   top: 50%;
   transform: translateY(-50%);
  height: 58cqh;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .panel.gone  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .msg-box  {
  position: absolute;
   inset: 0;
  background: rgba(3, 5, 12, .6);
  border: 6px solid color-mix(in srgb, var(--primary) 42%, white);
  border-radius: 10px;
  box-shadow:
    0 0 0 3.5px color-mix(in srgb, var(--primary) 80%, transparent),
    inset 0 0 0 3.5px color-mix(in srgb, var(--primary) 80%, transparent),
    0 0 22px var(--primary),
    0 0 60px var(--p-soft),
    0 0 150px var(--p-haze),
    inset 0 0 18px var(--p-haze),
    inset 0 0 60px color-mix(in srgb, var(--primary) 12%, transparent);
  opacity: 0;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .msg-fit  {
  position: absolute;
   left: 5.5%;
   right: 5.5%;
   top: 8%;
   bottom: 44%;
  display: flex;
   align-items: center;
   justify-content: center;
  text-align: center;
   overflow: hidden;
  opacity: 0;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .panel.no-name .msg-fit  {
   bottom: 10%;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .panel.no-msg .msg-fit  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .msg-fit span  {
  font-family: 'Anton', 'Arial Narrow', sans-serif;
  text-transform: uppercase;
  letter-spacing: .015em;
  line-height: 1.02;
  color: color-mix(in srgb, white 72%, var(--primary));
  text-shadow:
    0 0 2px rgba(255,255,255,.9),
    0 0 8px var(--primary),
    0 0 18px var(--primary),
    0 0 46px var(--p-soft),
    0 0 110px var(--p-haze);
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .name-script  {
  position: absolute;
   left: 0;
   right: 0;
   bottom: 8%;
  height: 34%;
  display: flex;
   align-items: center;
   justify-content: center;
  text-align: center;
   overflow: visible;
  opacity: 0;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .panel.no-msg .name-script  {
  top: 50%;
   bottom: auto;
   height: 60%;
  transform: translate(0, -50%);
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .panel.no-name .name-script  {
   display: none;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"] .name-script span  {
  font-family: 'Mr Dafoe', cursive;
  line-height: .95;
  color: var(--s-hot);
  -webkit-text-stroke: 0.014em color-mix(in srgb, var(--secondary) 55%, white);
  white-space: nowrap;
  transform: rotate(-3deg);
  text-shadow:
    0 0 8px var(--secondary),
    0 0 24px var(--secondary),
    0 0 60px var(--s-soft),
    0 0 130px var(--s-haze);
}
@keyframes dynNeonStrike  {
  0%    {
   opacity: 0;
   }
  6%    {
   opacity: 0;
   }
  7%    {
   opacity: 1;
   }
  9%    {
   opacity: .12;
   }
  14%   {
   opacity: 1;
   }
  16%   {
   opacity: .2;
   }
  24%   {
   opacity: .95;
   }
  28%   {
   opacity: .25;
   }
  38%   {
   opacity: 1;
   }
  46%   {
   opacity: .82;
   }
  55%   {
   opacity: 1;
   }
  100%  {
   opacity: 1;
   }
}
@keyframes dynNeonPhotoIn  {
  from  {
   opacity: 0;
   }
  to    {
   opacity: 1;
   }
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .trace,
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .msg-box,
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .msg-fit,
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .name-script  {
  opacity: 1;
  animation: dynNeonStrike var(--reveal-ms) both;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .trace:nth-child(1)  {
   animation-delay: 0ms;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .trace:nth-child(2)  {
   animation-delay: calc(var(--reveal-ms) * .04);
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .trace:nth-child(3)  {
   animation-delay: calc(var(--reveal-ms) * .08);
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .trace:nth-child(4)  {
   animation-delay: calc(var(--reveal-ms) * .12);
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .msg-box      {
   animation-delay: calc(var(--reveal-ms) * .10);
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .msg-fit      {
   animation-delay: calc(var(--reveal-ms) * .18);
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .name-script  {
   animation-delay: calc(var(--reveal-ms) * .28);
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on .photo-holder  {
  animation: dynNeonPhotoIn calc(var(--reveal-ms) * .5) calc(var(--reveal-ms) * .35) both ease;
}
@keyframes dynNeonIdleFlick  {
  0%, 95.4%, 97.2%, 100%  {
   opacity: 1;
   }
  96%    {
   opacity: .5;
   }
  96.6%  {
   opacity: 1;
   }
  98%    {
   opacity: .72;
   }
  98.6%  {
   opacity: 1;
   }
}
@keyframes dynNeonHum  {
  from  {
   filter: brightness(1);
   }
  to    {
   filter: brightness(1.18);
   }
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.idle .trace:nth-child(3)  {
   animation: dynNeonIdleFlick 8.5s linear infinite;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.idle .trace:nth-child(1)  {
   animation: dynNeonIdleFlick 13s linear infinite;
   animation-delay: -6s;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.idle .msg-box             {
   animation: dynNeonIdleFlick 7s linear infinite;
   animation-delay: -3s;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.idle .msg-fit             {
   animation: none;
   opacity: 1;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.idle .name-script         {
   animation: dynNeonHum 3.4s ease-in-out infinite alternate;
   }
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.idle .photo-holder        {
   animation: none;
   opacity: 1;
   }
@keyframes dynNeonFlickOff  {
  0%    {
   opacity: 1;
   }
  12%   {
   opacity: .15;
   }
  22%   {
   opacity: .85;
   }
  34%   {
   opacity: .1;
   }
  46%   {
   opacity: .5;
   }
  58%   {
   opacity: .08;
   }
  74%   {
   opacity: .18;
   }
  100%  {
   opacity: 0;
   }
}
@keyframes dynNeonPhotoOff  {
  from  {
   opacity: 1;
   }
  to    {
   opacity: 0;
   }
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.off .trace,
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.off .msg-box,
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.off .msg-fit,
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.off .name-script  {
  animation: dynNeonFlickOff var(--off-ms) both;
}
#dyn-message-theme[data-theme="tmpl-neon-nightclub"].on.off .photo-holder  {
  animation: dynNeonPhotoOff calc(var(--off-ms) * .8) both ease;
}

